def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            colors = [grid[r][c] for r in range(br*3, br*3+3) for c in range(bc*3, bc*3+3) if grid[r][c] not in (0, 5)]
            if colors:
                out[br][bc] = max(set(colors), key=colors.count)
    return out
